<?php use VazinCMS\Security; ?><section class="title"><div><h1>کیف پول مشتریان</h1><p>موجودی تفکیک‌شده بر اساس ارز و گردش قابل‌ردیابی</p></div></section>
<section class="grid wallet-totals"><?php foreach($totals as $t):?><article class="panel"><span class="muted">کل موجودی <?=Security::e($t['currency'])?></span><h2><?=Security::e($t['balance'])?></h2></article><?php endforeach;?></section>
<section class="panel"><h2>ساخت کیف پول</h2><form method="post" class="form-grid compact"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>مشتری<select name="user_id" required><option value="">انتخاب کنید</option><?php foreach($clients as $c):?><option value="<?=$c['id']?>"><?=Security::e($c['name'].' — '.$c['email'])?></option><?php endforeach;?></select></label><label>ارز<input name="currency" value="RUB" maxlength="8" required></label><button>ساخت یا نمایش کیف پول</button></form></section>
<section class="panel"><div class="title"><div><h2>کیف پول‌ها</h2></div><form method="get" class="inline"><input name="currency" value="<?=Security::e($currency)?>" placeholder="RUB"><button class="secondary">فیلتر</button></form></div><div class="table-wrap"><table><thead><tr><th>مشتری</th><th>ایمیل</th><th>ارز</th><th>موجودی</th><th>آخرین تغییر</th></tr></thead><tbody><?php foreach($wallets as $w):?><tr><td><a href="/admin/wallets/<?=$w['id']?>"><?=Security::e($w['customer'])?></a></td><td><?=Security::e($w['email'])?></td><td><?=Security::e($w['currency'])?></td><td><strong><?=Security::e($w['balance'])?></strong></td><td><?=Security::e($w['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div></section>
